// Shared verification primitives for the DeDi explorer and the evidence page.
//
// One copy, deliberately. This is the code that decides whether a proof holds,
// and two copies of it would eventually disagree — with the page that happens to
// be wrong still showing green ticks. It is also the code the test harness
// exercises against vectors generated by x/mod/sumdb/tlog, and a harness can only
// test the copy it reads.
//
// Everything here is pure: it takes bytes and returns whether they check out. It
// never fetches, so it cannot be talked out of a verdict by whoever served it.

// ---- crypto helpers ----
const te = new TextEncoder();
async function sha256(b){ return new Uint8Array(await crypto.subtle.digest('SHA-256', b)); }
function cat(...xs){ let n=0; for(const x of xs) n+=x.length; const o=new Uint8Array(n); let i=0;
  for(const x of xs){ o.set(x,i); i+=x.length; } return o; }
const leafHash = b => sha256(cat(new Uint8Array([0]), b));
const nodeHash = (l,r) => sha256(cat(new Uint8Array([1]), l, r));
function b64d(s){ const bin=atob(s); const u=new Uint8Array(bin.length);
  for(let i=0;i<bin.length;i++) u[i]=bin.charCodeAt(i); return u; }
function eq(a,b){ if(a.length!==b.length) return false; for(let i=0;i<a.length;i++) if(a[i]!==b[i]) return false; return true; }
function maxpow2(n){ let k=1; while((k<<1) < n) k<<=1; return k; } // largest power of two < n, n>=2

// Recursive RFC 6962 record-proof verification, matching x/mod/sumdb/tlog.
async function proofRoot(path, t, n, leaf){
  // The base case reached with a non-zero index means the index was never in
  // the tree: every legitimate recursion subtracts k until n is 0 at a leaf.
  // Without this a size-1 proof returned its leaf for ANY index, so an envelope
  // could claim leaf_index 999 in a tree of 1 and still fold to the signed
  // root. Go's tlog rejects that; this was the more permissive of the two.
  if(t===1){
    if(path.length!==0) throw new Error('proof len');
    if(n!==0) throw new Error('leaf index ' + n + ' is not in a tree of size 1');
    return leaf;
  }
  if(path.length===0) throw new Error('empty path');
  const k = maxpow2(t), top = path[path.length-1], rest = path.slice(0,-1);
  if(n < k){ return nodeHash(await proofRoot(rest, k, n, leaf), top); }
  return nodeHash(top, await proofRoot(rest, t-k, n-k, leaf));
}

// Canonical leaf preimage: MUST byte-match Go merkle.LeafBytes.
//
// The leaf preimage must be byte-identical to internal/merkle.LeafBytes, which
// builds it with Go's encoding/json — and Go escapes <, > and & in strings by
// default, plus U+2028 and U+2029. JSON.stringify escapes none of them.
//
// None of those characters is structural in JSON, so they can only appear
// inside a string value and replacing them in the finished output is exact.
//
// The store accepts them in a namespace, registry, record name or author, so
// without this a perfectly valid inclusion proof for a record named
// "a&b.example" is reported as not folding to the root — the verifier calling
// an honest node a liar.
const GO_ESCAPES = { '<': '\\u003c', '>': '\\u003e', '&': '\\u0026',
                     '\u2028': '\\u2028', '\u2029': '\\u2029' };
function goJSON(v){
  return JSON.stringify(v).replace(/[<>&\u2028\u2029]/g, c => GO_ESCAPES[c]);
}
function leafBytes(L){
  return te.encode(goJSON([
    "dedi/v1/leaf", L.entry_type, L.namespace, L.registry, L.record_name,
    L.version_num, L.digest, L.created_by, L.created_at ]));
}

// RFC 6962 consistency-proof verification, matching x/mod/sumdb/tlog.CheckTree.
// Proves the tree of size n with root h is a prefix of the tree of size t with
// root th — i.e. nothing already logged was changed or removed, only appended.
async function treeProofRun(p, lo, hi, n, old){
  if(n === hi){
    if(lo === 0){
      if(p.length !== 0) throw new Error('consistency proof: unexpected extra hashes');
      return [old, old];
    }
    if(p.length !== 1) throw new Error('consistency proof: wrong length');
    return [p[0], p[0]];
  }
  if(p.length === 0) throw new Error('consistency proof: proof is empty');
  const k = maxpow2(hi - lo);
  const top = p[p.length-1], rest = p.slice(0, -1);
  if(n <= lo + k){
    const [oh, th] = await treeProofRun(rest, lo, lo+k, n, old);
    return [oh, await nodeHash(th, top)];
  }
  const [oh, th] = await treeProofRun(rest, lo+k, hi, n, old);
  return [await nodeHash(top, oh), await nodeHash(top, th)];
}
async function checkTree(p, t, th, n, h){
  if(t < 1 || n < 1 || n > t) throw new Error('consistency proof: invalid tree sizes');
  if(n === t) return eq(th, h); // same tree: nothing to prove beyond equality
  const [h2, th2] = await treeProofRun(p, 0, t, n, h);
  return eq(th2, th) && eq(h2, h);
}

// Parse a sumdb/note: signed bytes = body (text incl. trailing \n); signatures
// follow a blank line as "— <name> <base64>".
function parseNote(txt){
  const m = txt.indexOf('\n\n— ');
  if(m < 0) return null;
  const body = txt.slice(0, m+1);
  const sigLine = txt.slice(m+2).split('\n')[0];
  const parts = sigLine.split(' ');
  return { body, sigB64: parts[parts.length-1] };
}
function parseCheckpointBody(body){
  const L = body.split('\n');
  return { origin:L[0], size:parseInt(L[1],10), rootB64:L[2], root:b64d(L[2]) };
}
async function verifyCheckpointSig(note, vkey){
  if(!vkey || !crypto.subtle) return null;
  try {
    const i1=vkey.indexOf('+'), i2=vkey.indexOf('+', i1+1);
    const pub = b64d(vkey.slice(i2+1)).slice(1); // drop 1 alg byte -> 32-byte pub
    const parsed = parseNote(note);
    const sig = b64d(parsed.sigB64).slice(4);    // 4-byte keyhash prefix + 64 sig
    const key = await crypto.subtle.importKey('raw', pub, {name:'Ed25519'}, false, ['verify']);
    return await crypto.subtle.verify('Ed25519', key, sig, te.encode(parsed.body));
  } catch(e){ return null; }
}

// ---- traced variants ----
//
// Same algorithms, but recording every hash combination so a page can show the
// derivation instead of a verdict. They exist because "verified ✓" is itself
// just an assertion unless the reader can see which bytes were combined in what
// order to get there. The untraced functions above remain the ones used for the
// answer; these must agree with them, and a test asserts that they do.

function b64e(u){ let s=''; for(const b of u) s += String.fromCharCode(b); return btoa(s); }

// proofRootTraced mirrors proofRoot, appending {left, right, out} per step.
async function proofRootTraced(path, t, n, leaf, steps){
  if(t===1){ if(path.length!==0) throw new Error('proof len'); return leaf; }
  if(path.length===0) throw new Error('empty path');
  const k = maxpow2(t), top = path[path.length-1], rest = path.slice(0,-1);
  if(n < k){
    const sub = await proofRootTraced(rest, k, n, leaf, steps);
    const out = await nodeHash(sub, top);
    steps.push({left: sub, right: top, out, side: 'sibling on the right'});
    return out;
  }
  const sub = await proofRootTraced(rest, t-k, n-k, leaf, steps);
  const out = await nodeHash(top, sub);
  steps.push({left: top, right: sub, out, side: 'sibling on the left'});
  return out;
}

// treeProofRunTraced mirrors treeProofRun, recording the combinations used to
// rebuild both the old and the new root.
async function treeProofRunTraced(p, lo, hi, n, old, steps){
  if(n === hi){
    if(lo === 0){
      if(p.length !== 0) throw new Error('consistency proof: unexpected extra hashes');
      return [old, old];
    }
    if(p.length !== 1) throw new Error('consistency proof: wrong length');
    return [p[0], p[0]];
  }
  if(p.length === 0) throw new Error('consistency proof: proof is empty');
  const k = maxpow2(hi - lo);
  const top = p[p.length-1], rest = p.slice(0, -1);
  if(n <= lo + k){
    const [oh, th] = await treeProofRunTraced(rest, lo, lo+k, n, old, steps);
    const out = await nodeHash(th, top);
    steps.push({left: th, right: top, out, note: 'extends the new tree to the right'});
    return [oh, out];
  }
  const [oh, th] = await treeProofRunTraced(rest, lo+k, hi, n, old, steps);
  const oOut = await nodeHash(top, oh), tOut = await nodeHash(top, th);
  steps.push({left: top, right: oh, out: oOut, note: 'rebuilds the old root'});
  steps.push({left: top, right: th, out: tOut, note: 'rebuilds the new root'});
  return [oOut, tOut];
}

async function checkTreeTraced(p, t, th, n, h, steps){
  if(t < 1 || n < 1 || n > t) throw new Error('consistency proof: invalid tree sizes');
  if(n === t) return {ok: eq(th, h), oldRoot: h, newRoot: th, trivial: true};
  const [h2, th2] = await treeProofRunTraced(p, 0, t, n, h, steps);
  return {ok: eq(th2, th) && eq(h2, h), oldRoot: h2, newRoot: th2, trivial: false};
}
